<script setup>
import {computed} from 'vue';
import {useTaskManager} from '../composables/useTaskManager';
import {PRI_KEYS,STATUSES,TK_PRI,TK_STATUSES,UPD_TYPES,WEEKDAYS,EMPLOYEE_INVOLVED_ISSUES} from '../lib/task-domain';
import NativeTable from '../components/native/NativeTable.vue';
import NativeMultiSelect from '../components/native/NativeMultiSelect.vue';
import NativeDialog from '../components/native/NativeDialog.vue';
import TaskControlPanel from '../components/tasks/TaskControlPanel.vue';
const vm=useTaskManager();
const {taskAssignedBy,taskDept,taskDesig,taskReport,taskGroup,teamBranch,teamDept,exportFormat,S,d,loading,busy,error,notice,canWrite,peopleOptions,taskSearch,taskStatus,taskBranch,taskPerson,taskCategory,taskPriority,taskFrom,taskTo,taskMode,myView,ticketSearch,ticketStatus,ticketCategory,ticketBranch,ticketPriority,ticketResolver,teamSearch,reportDim,taskRows,ticketRows,stats,reportRows,team,selected,drawer,update,actionOpen,action,confirmAssign,queueOpen,queueUser,queueIds,dispatch,dispatchRows,previewUser,phoneCode,configOpen,config,load,selectTask,selectTicket,preview,chooseGroup,addFiles,prepareAssign,assign,requestAction,applyAction,postUpdate,saveProgress,toggleChecklist,manageQueue,moveQueue,saveQueue,ticketCategoryChanged,submitTicket,openConfig,saveConfig,unlockPhones,exportData}=vm;
const taskColumns=[{k:'no',l:'Task'},{k:'title',l:'Title'},{k:'assignee',l:'Assignee',v:r=>d.personName(r.assignee)},{k:'by',l:'Assigned by',v:r=>d.personName(r.by)},{k:'branch',l:'Branch'},{k:'cat',l:'Category'},{k:'pri',l:'Priority',v:r=>d.PRI_N(r.pri)+' '+d.PRI_L(r.pri)},{k:'status',l:'Status'},{k:'q',l:'Queue',v:r=>d.qRank(r)},{k:'due',l:'Due',v:r=>d.fDT(r.due)},{k:'progress',l:'Progress'},{k:'report',l:'Reporting',v:r=>d.repText(r.report)}];
const ticketColumns=[{k:'id',l:'Ticket'},{k:'subject',l:'Issue'},{k:'branch',l:'Branch'},{k:'cat',l:'Category'},{k:'raiser',l:'Raised by',v:r=>d.personName(r.raiser)},{k:'tag',l:'Resolver',v:r=>d.personName(r.tag)},{k:'pri',l:'Priority'},{k:'status',l:'Status'},{k:'sla',l:'SLA',v:r=>d.tkBreach(r)?'Breached':d.fDT(d.localStr(d.tkSla(r)||new Date()))}];
const reportColumns=[{k:'name',l:'Group'},{k:'n',l:'Tasks'},{k:'open',l:'Open'},{k:'prog',l:'In Progress'},{k:'rev',l:'Review'},{k:'done',l:'Completed'},{k:'cxl',l:'Cancelled'},{k:'od',l:'Overdue'},{k:'ontime',l:'On Time'},{k:'late',l:'Late'},{k:'pct',l:'On Time %'},{k:'avg',l:'Avg days'},{k:'missed',l:'Missed reports'}];
const tiles=computed(()=>[['All',stats.value.n,''],['Open',stats.value.open,'Active'],['In Progress',stats.value.prog,'In Progress'],['Review Pending',stats.value.rev,'Review Pending'],['Completed',stats.value.done,'Completed'],['Overdue',stats.value.od,'Overdue']]);
const taskActions=computed(()=>{const t=selected.value;if(!t||S.openTicket)return [];const list=[];if(d.isAssignee(t)&&!d.isClosed(t)){if(['Open','Reopened','On Hold'].includes(t.status))list.push(['start','Start']);list.push(['report','Report']);if(t.status!=='Review Pending')list.push(['submit','Done → Review']);}if(d.canManage(t)){if(t.status==='Review Pending')list.push(['approve','Approve & close']);if(d.isClosed(t))list.push(['reopen','Reopen']);else{list.push(['closeNow','Close completed'],['hold','Hold'],['extend','Extend deadline'],['pri','Priority'],['top','Move to #1'],['cancel','Cancel']);if(!t.grp)list.push(['reassign','Reassign']);}}if(!d.isClosed(t))list.push(['remind','Remind']);return list;});
const ticketActions=computed(()=>{const t=selected.value;if(!t||!S.openTicket)return [];const list=[];if(d.can('t_manage')||t.tag===S.me.user){if(d.tkActive(t))list.push(['resolve','Mark resolved']);list.push(['hold','Hold'],['unhold','Resume'],['retag','Change resolver'],['tpri','Priority']);}if(t.raiser===S.me.user||d.can('t_manage')){if(t.status==='Resolved')list.push(['close','Close']);if(['Resolved','Closed'].includes(t.status))list.push(['reopen','Reopen']);}list.push(['remind','Remind']);return list;});
const selectedFiles=computed(()=>selected.value?(S.openTicket?S.tfiles[selected.value.id]:S.files[d.fileKey(selected.value)])||[]:[]);
const print=()=>window.print();
</script>
<template><section class="tasks-page"><div id="life-tm">
<header class="header"><div><h1>Task Manager & Ticket System</h1><p>{{S.me.name}} · {{S.me.role}} <strong v-if="S.me.preview">Preview · changes blocked</strong></p></div><nav><button v-if="d.mod('tasks')" :class="{on:S.mod==='task'}" @click="S.mod='task'">Tasks</button><button v-if="d.mod('tickets')" :class="{on:S.mod==='ticket'}" @click="S.mod='ticket'">Tickets / Helpdesk</button><button :disabled="busy||loading" @click="load">Refresh</button><button v-if="S.realMe?.admin&&!S.me.preview" @click="openConfig">Control Panel</button><button v-if="d.can('export')" @click="print">Print</button></nav></header>
<p v-if="error" role="alert" class="bn r">{{error}} <button :disabled="busy" @click="error=''">Dismiss</button></p><p v-if="notice" role="status" class="bn g">{{notice}}</p><p v-if="loading" role="status">Loading tasks, tickets, employees and settings…</p>
<div v-if="d.can('viewas')&&d.mod('viewas')||S.me.preview" class="fbar"><label>View as employee<select v-model="previewUser" :disabled="busy" @change="preview"><option value="">My own view</option><option v-for="p in S.people.filter(p=>p.login)" :key="p.user" :value="p.user">{{p.name}}</option></select></label></div>
<label v-if="d.can('export')">Export format<select v-model="exportFormat"><option value="csv">CSV</option><option value="excel">Excel</option></select></label>
<nav class="tabs"><button v-for="[key,label] in S.mod==='task'?d.taskTabs():d.ticketTabs()" :key="key" class="tab" :class="{on:S.tab[S.mod]===key}" @click="S.tab[S.mod]=key">{{label}}</button></nav>
<template v-if="S.mod==='task'">
<div class="kpis"><button v-for="[label,value,status] in tiles" :key="label" class="kpi" @click="S.tab.task='all';taskStatus=status"><strong>{{value}}</strong><span>{{label}}</span></button></div>
<form v-if="S.tab.task==='assign'&&S.form" class="card cb" @submit.prevent="prepareAssign"><fieldset :disabled="!canWrite||!d.can('assign')"><h2>Assign New Task</h2><div class="form-grid"><label>Assign by<select v-model="S.form.mode" @change="S.form.sel=[]"><option value="emp">Employees</option><option value="branch">Branch</option><option value="dept">Department</option><option value="desig">Designation</option></select></label><NativeMultiSelect v-if="S.form.mode==='emp'" v-model="S.form.sel" label="Assignees" :options="peopleOptions"/><template v-else><NativeMultiSelect v-if="S.form.mode==='branch'" v-model="S.form.selBranches" label="Branches" :options="d.allBranches()" @update:model-value="chooseGroup"/><NativeMultiSelect v-if="S.form.mode==='dept'" v-model="S.form.selDepts" label="Departments" :options="d.distinct('dept')" @update:model-value="chooseGroup"/><NativeMultiSelect v-if="S.form.mode==='desig'" v-model="S.form.selDesigs" label="Designations" :options="d.distinct('desig')" @update:model-value="chooseGroup"/><NativeMultiSelect v-model="S.form.sel" label="Selected people" :options="peopleOptions"/></template>
<label>Category<select v-model="S.form.cat" required><option value="">Select</option><option v-for="cat in d.categories()" :key="cat">{{cat}}</option></select></label><label>Title<input v-model="S.form.title" maxlength="80" required></label><label>Priority<select v-model="S.form.pri" required><option value="">Select</option><option v-for="p in PRI_KEYS" :key="p" :value="p">{{d.PRI_N(p)}} · {{d.PRI_L(p)}}</option></select></label><label>Start<input v-model="S.form.start" type="datetime-local" required></label><label>Due<input v-model="S.form.due" type="datetime-local" required></label><label><input v-model="S.form.top" type="checkbox">Force to queue #1</label>
<label v-if="S.form.sel.length>1&&d.can('group')&&d.mod('group')"><input v-model="S.form.asGroup" type="checkbox">One group task</label><template v-if="S.form.asGroup"><label>Group response<select v-model="S.form.response"><option value="group">Any member completes for everyone</option><option value="individual">Each member completes their part</option></select></label><label>Leader<select v-model="S.form.leader"><option value="">First selected person</option><option v-for="u in S.form.sel" :key="u" :value="u">{{d.personName(u)}}</option></select></label></template>
<label>Reporting rule<select v-model="S.form.report.type" :required="d.mod('repMandatory')"><option value="">Select reporting</option><option v-for="r in d.reportTypes()" :key="r.k" :value="r.k">{{r.label}}</option></select></label><label v-if="['EOD','WEEKLY','MONTHLY'].includes(S.form.report.type)">Report time<input v-model="S.form.report.time" type="time"></label><label v-if="S.form.report.type==='WEEKLY'">Weekday<select v-model.number="S.form.report.day"><option v-for="(name,i) in WEEKDAYS" :key="name" :value="i">{{name}}</option></select></label><label v-if="S.form.report.type==='MONTHLY'">Day of month<input v-model.number="S.form.report.dom" type="number" min="1" max="31"></label><label v-if="S.form.report.type==='SPECIFIC'">Report date & time<input v-model="S.form.report.dt" type="datetime-local" required></label><NativeMultiSelect v-model="S.form.cc" label="CC · you are always included" :options="peopleOptions"/></div>
<label>Task details · {{d.words(S.form.details)}} / 150 words<textarea v-model="S.form.details" required/></label><label v-if="d.mod('checklist')">Checklist · one step per line<textarea v-model="S.form.checklist"/></label><div class="row"><label v-if="d.mod('email')"><input v-model="S.form.email" type="checkbox">Email notifications</label><label v-if="d.mod('wa')"><input v-model="S.form.wa" type="checkbox">WhatsApp links after assignment</label><label>Attachments · max 5 MB each<input type="file" multiple @change="addFiles($event,S.pendingFiles)"></label></div><div class="chips"><span v-for="(file,i) in S.pendingFiles" :key="i">{{file.name}}<button type="button" @click="S.pendingFiles.splice(i,1)">×</button></span></div><div class="row"><button class="btn pri" type="submit">Preview & Assign</button><button type="button" @click="d.resetForm">Clear</button></div></fieldset><aside v-if="d.mod('recent')"><h3>Recently assigned by me</h3><button v-for="t in S.tasks.filter(t=>t.by===S.me.user).slice(0,5)" :key="t.id" type="button" class="btn" @click="selectTask(t)">{{d.dispNo(t)}} · {{t.title}}</button></aside></form>
<section v-else-if="S.tab.task==='team'&&d.can('team')&&d.mod('team')"><input v-model="teamSearch" type="search" placeholder="Search team"><select v-model="teamBranch"><option value="">All branches</option><option v-for="b in d.allBranches()" :key="b">{{b}}</option></select><select v-model="teamDept"><option value="">All departments</option><option v-for="dept in d.distinct('dept')" :key="dept">{{dept}}</option></select><button v-if="d.can('export')" @click="exportData('team')">Export team</button><div v-if="S.cfg.phone.codeHash&&!d.phonesOpen()"><input v-model="phoneCode" type="password" placeholder="Phone unlock code"><button @click="unlockPhones">Unlock numbers</button></div><NativeTable :columns="[{k:'name',l:'Employee'},{k:'desig',l:'Designation'},{k:'dept',l:'Department'},{k:'branch',l:'Branch'},{k:'mobile',l:'Mobile'},{k:'user',l:'ERP Login'},{k:'open',l:'Open'},{k:'overdue',l:'Overdue'}]" :rows="team" :total="false"><template #cell="{row,column,value}"><span>{{value}}</span><template v-if="column.k==='name'&&row.login"><button v-if="d.can('assign')" @click="S.tab.task='assign';S.form.sel=[row.user]">Assign</button><button @click="manageQueue(row.user)">Queue</button></template></template></NativeTable></section>
<section v-else><div class="fbar"><input v-model="taskSearch" type="search" placeholder="Task, title, person, branch"><select v-model="taskStatus"><option value="">All statuses</option><option>Active</option><option>Overdue</option><option>Reports Due</option><option v-for="st in STATUSES" :key="st">{{st}}</option></select><select v-model="taskBranch"><option value="">All branches</option><option v-for="b in d.allBranches()" :key="b">{{b}}</option></select><select v-model="taskPerson"><option value="">All assignees</option><option v-for="p in peopleOptions" :key="p.value" :value="p.value">{{p.label}}</option></select><select v-model="taskCategory"><option value="">All categories</option><option v-for="cat in d.categories()" :key="cat">{{cat}}</option></select><select v-model="taskPriority"><option value="">All priorities</option><option v-for="p in PRI_KEYS" :key="p" :value="p">{{d.PRI_L(p)}}</option></select><select v-model="taskAssignedBy"><option value="">All assigners</option><option v-for="p in peopleOptions" :key="p.value" :value="p.value">{{p.label}}</option></select><select v-model="taskDept"><option value="">All departments</option><option v-for="dept in d.distinct('dept')" :key="dept">{{dept}}</option></select><select v-model="taskDesig"><option value="">All designations</option><option v-for="designation in d.distinct('desig')" :key="designation">{{designation}}</option></select><select v-model="taskReport"><option value="">All reporting rules</option><option v-for="rule in d.reportTypes()" :key="rule.k" :value="rule.k">{{rule.label}}</option></select><select v-model="taskGroup"><option value="">All task types</option><option value="group">Group tasks</option><option value="individual">Individual tasks</option></select><input v-model="taskFrom" type="date" aria-label="Created from"><input v-model="taskTo" type="date" aria-label="Created to"><button v-if="d.can('export')" @click="exportData(S.tab.task==='reports'?'reports':'tasks')">Export</button></div>
<template v-if="S.tab.task==='reports'&&d.can('reports')&&d.mod('reports')"><label>Group by<select v-model="reportDim"><option v-for="dim in ['assignee','branch','dept','desig','by','cat','pri']" :key="dim">{{dim}}</option></select></label><NativeTable :rows="reportRows" :columns="reportColumns"/></template>
<template v-else><nav v-if="S.tab.task==='my'"><button v-for="[key,label] in [['tome','To Me'],['byme','By Me'],['cc','CC'],['groups','Groups'],['done','Completed / Cancelled']]" :key="key" @click="myView=key">{{label}}</button></nav><nav><button @click="taskMode='table'">Table</button><button @click="taskMode='queue'">Queue by Assignee</button><button @click="taskMode='board'">Status Board</button></nav><NativeTable v-if="taskMode==='table'" :rows="taskRows" :columns="taskColumns" :total="false" @open="selectTask"><template #cell="{row,column,value}"><button v-if="column.k==='title'" class="link" @click="selectTask(row)">{{row.grp?'👥 ':''}}{{value}}</button><span v-else :class="{red:column.k==='due'&&d.isOverdue(row)}">{{value}}</span></template></NativeTable><div v-else-if="taskMode==='queue'" class="board"><section v-for="user in [...new Set(taskRows.map(t=>t.assignee))]" :key="user" class="card cb"><h3>{{d.personName(user)}}</h3><button :disabled="!canWrite" @click="manageQueue(user)">Manage Queue</button><button v-for="t in taskRows.filter(t=>t.assignee===user)" :key="t.id" class="task-card" @click="selectTask(t)">#{{d.qRank(t)}} · {{t.title}} · {{t.status}}</button></section></div><div v-else class="board"><section v-for="status in STATUSES" :key="status" class="card cb"><h3>{{status}}</h3><button v-for="t in taskRows.filter(t=>t.status===status)" :key="t.id" class="task-card" @click="selectTask(t)">{{t.title}} · {{d.personName(t.assignee)}}</button></section></div></template></section>
</template>
<template v-else><form v-if="S.tab.ticket==='traise'&&S.tform" class="card cb" @submit.prevent="submitTicket"><fieldset :disabled="!canWrite||!d.can('t_raise')"><h2>Raise New Ticket</h2><div class="form-grid"><label>Branch<select v-model="S.tform.branch"><option v-for="b in d.allBranches()" :key="b">{{b}}</option></select></label><label>Category<select v-model="S.tform.cat" required @change="ticketCategoryChanged"><option value="">Select category</option><option v-for="c in d.tCats()" :key="c">{{c}}</option></select></label><label>Issue<select v-model="S.tform.issue" required><option value="">Select issue</option><option v-for="i in d.tIssues(S.tform.cat)" :key="i">{{i}}</option></select></label><label v-if="S.tform.issue==='Other'">Describe issue<input v-model="S.tform.other" required></label><label v-if="EMPLOYEE_INVOLVED_ISSUES.includes(S.tform.issue)">Employee involved<select v-model="S.tform.emp" required><option value="">Choose</option><option v-for="p in S.people" :key="p.emp||p.user">{{p.name}}</option></select></label><label>Priority<select v-model="S.tform.pri" required><option value="">Choose</option><option v-for="p in TK_PRI" :key="p">{{p}}</option></select></label><label>Resolver<select v-model="S.tform.tag" required><option value="">Choose resolver</option><option v-for="p in peopleOptions" :key="p.value" :value="p.value">{{p.label}}</option></select></label><NativeMultiSelect v-model="S.tform.cc" label="CC" :options="peopleOptions"/></div><label>Details<textarea v-model="S.tform.details" required/></label><label>Attachments<input type="file" multiple @change="addFiles($event,S.tFiles)"></label><span v-for="(file,i) in S.tFiles" :key="i">{{file.name}} <button type="button" @click="S.tFiles.splice(i,1)">Remove</button></span><label v-if="d.mod('email')"><input v-model="S.tform.email" type="checkbox">Email resolver</label><label v-if="d.mod('wa')"><input v-model="S.tform.wa" type="checkbox">WhatsApp link</label><button class="btn pri" type="submit">Submit Ticket</button><button type="button" @click="d.resetTForm">Clear</button></fieldset></form><section v-else><div class="fbar"><input v-model="ticketSearch" type="search" placeholder="Search tickets"><select v-model="ticketStatus"><option value="">All statuses</option><option>Active</option><option v-for="status in TK_STATUSES" :key="status">{{status}}</option></select><select v-model="ticketCategory"><option value="">All categories</option><option v-for="cat in d.tCats()" :key="cat">{{cat}}</option></select><select v-model="ticketBranch"><option value="">All branches</option><option v-for="b in d.allBranches()" :key="b">{{b}}</option></select><select v-model="ticketPriority"><option value="">All priorities</option><option v-for="p in TK_PRI" :key="p">{{p}}</option></select><select v-model="ticketResolver"><option value="">All resolvers</option><option v-for="p in peopleOptions" :key="p.value" :value="p.value">{{p.label}}</option></select><button v-if="d.can('export')" @click="exportData('tickets')">Export tickets</button></div><NativeTable :columns="ticketColumns" :rows="ticketRows" :total="false" @open="selectTicket"><template #cell="{row,column,value}"><button v-if="column.k==='subject'" class="link" @click="selectTicket(row)">{{value}}</button><span v-else>{{value}}</span></template></NativeTable></section></template>
<NativeDialog v-model="confirmAssign" title="Confirm Assignment" :busy="busy"><p>{{S.form?.asGroup?'One group task':'Individual tasks'}} · {{S.form?.sel.length}} people · {{S.form?.title}}</p><ul><li v-for="user in S.form?.sel||[]" :key="user">{{d.personName(user)}} · current open {{d.queueOf(user).length}} · new queue #{{d.placement(user,S.form.pri,S.form.top).rank}}</li></ul><p>Due {{d.fDT(S.form?.due)}} · {{d.repText(S.form?.report)}}</p><button :disabled="!canWrite" @click="assign">Confirm & Assign</button></NativeDialog>
<NativeDialog v-model="drawer" :title="selected?(S.openTicket?selected.id:d.dispNo(selected))+' · '+(selected.title||selected.subject):'Details'" :busy="busy"><template v-if="selected"><p>{{selected.status}} · {{selected.pri}} · {{selected.branch}}</p><p class="preserve-text">{{selected.details}}</p><p>{{S.openTicket?'Resolver':'Assignee'}}: {{d.personName(S.openTicket?selected.tag:selected.assignee)}} · {{S.openTicket?'Raised':'Assigned'}} by {{d.personName(S.openTicket?selected.raiser:selected.by)}}</p><template v-if="!S.openTicket"><p>Start {{d.fDT(selected.start)}} · Due {{d.fDT(selected.due)}} · {{d.repText(selected.report)}} · Queue #{{d.qRank(selected)}}</p><p v-if="d.reportDue(selected)">{{d.reportDue(selected).label}} {{d.reportDue(selected).late?'· OVERDUE':''}}</p><label v-for="(item,i) in selected.checklist" :key="i"><input type="checkbox" :checked="item.d" :disabled="!canWrite||d.isClosed(selected)" @change="toggleChecklist(i)">{{item.t}}</label><label>Progress {{update.progress}}%<input v-model.number="update.progress" type="range" min="0" max="100" :disabled="!canWrite||d.isClosed(selected)"></label><button :disabled="!canWrite||d.isClosed(selected)" @click="saveProgress">Save progress</button><div v-if="selected.grp"><h3>Group members · {{selected.grp.response}} response</h3><p v-for="user in selected.grp.members" :key="user">{{d.personName(user)}} · {{S.tasks.find(t=>t.mid===selected.mid&&t.assignee===user)?.status}}</p></div><h3 v-if="selected.delays.length">Deadline history</h3><p v-for="(delay,i) in selected.delays" :key="i">{{d.fDT(delay.old_deadline)}} → {{d.fDT(delay.new_deadline)}} · {{delay.remarks}}</p></template><h3>Attachments</h3><a v-for="file in selectedFiles" :key="file.name||file.file_url" :href="file.file_url" target="_blank" rel="noopener">{{file.file_name||file.name}}</a><h3>Updates and Reports</h3><article v-for="(item,i) in selected.updates.slice().reverse()" :key="item.id||i" class="update"><b>{{item.type}} · {{d.personName(item.by)}} · {{d.fDT(item.at)}}</b><p class="preserve-text">{{item.text}}</p><a v-for="file in item.files||[]" :key="file.url" :href="file.url" target="_blank" rel="noopener">{{file.name}}</a></article><form v-if="S.openTicket?!d.tkClosed(selected):!d.isClosed(selected)" @submit.prevent="postUpdate"><select v-if="!S.openTicket" v-model="update.type"><option v-for="type in UPD_TYPES" :key="type">{{type}}</option></select><textarea v-model="update.text" placeholder="Update, report, delay remark or query" required/><input type="file" multiple @change="addFiles($event,update.files)"><button :disabled="!canWrite">Post update</button></form><div class="row"><button v-for="[kind,label] in S.openTicket?ticketActions:taskActions" :key="kind" :disabled="!canWrite" @click="requestAction(kind,selected,!!S.openTicket)">{{label}}</button></div></template></NativeDialog>
<NativeDialog v-model="actionOpen" :title="action.kind+' · '+action.id" :busy="busy"><form @submit.prevent="applyAction"><label v-if="action.kind==='extend'">New deadline<input v-model="action.due" type="datetime-local" required></label><label v-if="['pri','tpri'].includes(action.kind)">Priority<select v-model="action.priority"><option v-for="priority in action.ticket?TK_PRI:PRI_KEYS" :key="priority">{{priority}}</option></select></label><label v-if="action.kind==='pri'"><input v-model="action.reorder" type="checkbox">Re-position queue by priority</label><label v-if="['retag','reassign'].includes(action.kind)">Employee<select v-model="action.person" required><option v-for="p in peopleOptions" :key="p.value" :value="p.value">{{p.label}}</option></select></label><label v-if="!action.ticket&&d.findTask(action.id)&&d.isAssignee(d.findTask(action.id))&&d.needsDelayRemark(d.findTask(action.id))">Overdue delay reason<textarea v-model="action.delay"/></label><label>Remarks<textarea v-model="action.remarks"/></label><button :disabled="!canWrite">Confirm {{action.kind}}</button></form></NativeDialog>
<NativeDialog v-model="queueOpen" :title="'Queue · '+d.personName(queueUser)" :busy="busy"><ol><li v-for="(id,index) in queueIds" :key="id">{{d.findTask(id)?.title}}<button :disabled="index===0||busy" @click="moveQueue(index,-1)">↑</button><button :disabled="index===queueIds.length-1||busy" @click="moveQueue(index,1)">↓</button></li></ol><button :disabled="!canWrite" @click="saveQueue">Save queue</button></NativeDialog>
<NativeDialog v-model="dispatch" title="Notifications"><p>Saved successfully. Open WhatsApp to send a message to the selected person.</p><a v-for="row in dispatchRows" :key="row.user" :href="row.phone?'https://wa.me/'+row.phone+'?text='+encodeURIComponent(row.text):undefined" target="_blank" rel="noopener">{{row.name}} · {{row.phone?'Open WhatsApp':'Mobile unavailable'}}</a></NativeDialog>
<NativeDialog v-model="configOpen" title="Control Panel" :busy="busy"><TaskControlPanel v-if="config" v-model="config" :people="S.people" :disabled="busy"/><button :disabled="!canWrite" @click="saveConfig">Save Control Panel</button></NativeDialog>
</div></section></template>
